# File: four-locations-flow.sh — move a change through ALL four locations.

# --- WORKING DIRECTORY ---
# Edit two relevant files + one unrelated experiment file.
# git status shows all three as modified (red): "not staged for commit".
git status

# --- WORKING DIRECTORY -> STAGING AREA (git add) ---
# Stage ONLY the two files for THIS logical change. Leave Experiment.java out.
git add src/main/java/com/bank/transfers/TransferLimitService.java
git add src/test/java/com/bank/transfers/TransferLimitServiceTest.java
git status   # the two show green "changes to be committed"; Experiment stays red

# --- STAGING AREA -> LOCAL REPOSITORY (git commit) ---
# Record the staged snapshot as one commit. No network needed.
git commit -m "TRF-77 enforce daily transfer limit of 500000"

# --- REMOTE -> LOCAL (git fetch) before pushing ---
# A teammate pushed to main. FETCH downloads it WITHOUT touching my files.
git fetch origin
git log --oneline origin/main -3   # inspect what they changed, safely

# Integrate their work into my branch (merge or rebase), resolve any conflict.
git merge origin/main
# (git pull would have done fetch + merge in ONE step.)

# --- LOCAL REPOSITORY -> REMOTE (git push) ---
# Now my branch is up to date and ahead; publish my commit to the vault.
git push origin feature/transfer-limit
```

```bash
# File: undo-helpers.sh — moving changes BACKWARD between locations.

# Unstage a file (STAGING -> WORKING DIRECTORY), keeping the edit.
git restore --staged src/main/java/com/bank/transfers/Experiment.java

# Discard a working-directory edit entirely (CAREFUL: destroys the change).
git restore src/main/java/com/bank/transfers/Experiment.java
```

