package com.bank.transfers;

import java.math.BigDecimal;

// The feature that flows through working dir -> staging -> local -> remote.
public class TransferLimitService {

    private static final BigDecimal DAILY_LIMIT = new BigDecimal("500000");

    // Reject a transfer that would exceed the daily limit for an account.
    public boolean isWithinDailyLimit(BigDecimal alreadyTransferredToday,
                                      BigDecimal newTransfer) {
        BigDecimal total = alreadyTransferredToday.add(newTransfer);
        return total.compareTo(DAILY_LIMIT) <= 0;
    }
}
