package com.bank.transfers;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

class TransferLimitServiceTest {

    private final TransferLimitService service = new TransferLimitService();

    @Test
    void allowsWithinLimit() {
        // Rajesh already moved 300000 today; another 100000 is fine (<=500000).
        assertTrue(service.isWithinDailyLimit(new BigDecimal("300000"), new BigDecimal("100000")));
    }

    @Test
    void rejectsOverLimit() {
        // Already 400000 today; another 200000 exceeds 500000.
        assertFalse(service.isWithinDailyLimit(new BigDecimal("400000"), new BigDecimal("200000")));
    }
}
